-- Oracle 19c compatible schema. IDs use identity keys; critical service workflows lock rows FOR UPDATE.
CREATE TABLE MEMBERS (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR2(200) NOT NULL, first_name VARCHAR2(100) NOT NULL, last_name VARCHAR2(100) NOT NULL, email VARCHAR2(320) NOT NULL UNIQUE, phone VARCHAR2(40) NOT NULL UNIQUE, date_of_birth DATE, address VARCHAR2(1000), emergency_contact VARCHAR2(300), joining_date DATE NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, status VARCHAR2(12) NOT NULL CHECK (status IN ('ACTIVE','INACTIVE','SUSPENDED')));
CREATE TABLE MEMBERSHIP_PLANS (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR2(200) NOT NULL UNIQUE, duration_days NUMBER(6) NOT NULL CHECK (duration_days > 0), price NUMBER(12,2) NOT NULL CHECK (price >= 0), visit_limit NUMBER(8) CHECK (visit_limit > 0), is_active NUMBER(1) NOT NULL CHECK (is_active IN (0,1)));
CREATE TABLE MEMBERSHIPS (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, member_id NUMBER NOT NULL REFERENCES MEMBERS(id), plan_id NUMBER NOT NULL REFERENCES MEMBERSHIP_PLANS(id), start_date DATE NOT NULL, end_date DATE NOT NULL, price_paid NUMBER(12,2) NOT NULL CHECK(price_paid >= 0), remaining_visits NUMBER(8), status VARCHAR2(12) NOT NULL CHECK(status IN ('ACTIVE','SUSPENDED','CANCELLED','EXPIRED')), CHECK(end_date >= start_date), CHECK(remaining_visits IS NULL OR remaining_visits >= 0));
CREATE TABLE TRAINERS (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR2(200) NOT NULL, email VARCHAR2(320) NOT NULL UNIQUE, phone VARCHAR2(40) NOT NULL UNIQUE, specialization VARCHAR2(300), status VARCHAR2(12) NOT NULL CHECK(status IN ('ACTIVE','INACTIVE','ON_LEAVE')), max_members NUMBER(8) CHECK(max_members > 0));
CREATE TABLE TRAINER_ASSIGNMENTS (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, trainer_id NUMBER NOT NULL REFERENCES TRAINERS(id), member_id NUMBER NOT NULL REFERENCES MEMBERS(id), assigned_at TIMESTAMP NOT NULL, CONSTRAINT uq_trainer_member UNIQUE(trainer_id, member_id));
CREATE TABLE ATTENDANCE (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, member_id NUMBER NOT NULL REFERENCES MEMBERS(id), membership_id NUMBER NOT NULL REFERENCES MEMBERSHIPS(id), check_in_at TIMESTAMP NOT NULL, check_out_at TIMESTAMP, duration_minutes NUMBER(10), CHECK(check_out_at IS NULL OR check_out_at >= check_in_at));
CREATE TABLE WORKOUT_PLANS (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, member_id NUMBER NOT NULL REFERENCES MEMBERS(id), trainer_id NUMBER NOT NULL REFERENCES TRAINERS(id), name VARCHAR2(200) NOT NULL, description VARCHAR2(2000), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE WORKOUT_EXERCISES (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workout_plan_id NUMBER NOT NULL REFERENCES WORKOUT_PLANS(id) ON DELETE CASCADE, name VARCHAR2(200) NOT NULL, sets NUMBER(5), repetitions NUMBER(5), weight NUMBER(10,2), duration_seconds NUMBER(8), rest_seconds NUMBER(8), difficulty VARCHAR2(30));
CREATE TABLE GYM_CLASSES (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR2(200) NOT NULL, trainer_id NUMBER NOT NULL REFERENCES TRAINERS(id), scheduled_at TIMESTAMP NOT NULL, capacity NUMBER(8) NOT NULL CHECK(capacity > 0), status VARCHAR2(12) NOT NULL CHECK(status IN ('SCHEDULED','CANCELLED')));
CREATE TABLE CLASS_ENROLLMENTS (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, class_id NUMBER NOT NULL REFERENCES GYM_CLASSES(id), member_id NUMBER NOT NULL REFERENCES MEMBERS(id), enrolled_at TIMESTAMP NOT NULL, status VARCHAR2(12) NOT NULL CHECK(status IN ('ENROLLED','CANCELLED')), CONSTRAINT uq_class_member UNIQUE(class_id, member_id));
CREATE TABLE PAYMENTS (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, member_id NUMBER NOT NULL REFERENCES MEMBERS(id), membership_id NUMBER REFERENCES MEMBERSHIPS(id), amount NUMBER(12,2) NOT NULL CHECK(amount > 0), method VARCHAR2(20) NOT NULL CHECK(method IN ('CASH','CARD','UPI','BANK_TRANSFER','OTHER')), reference_id VARCHAR2(200) NOT NULL UNIQUE, status VARCHAR2(12) NOT NULL CHECK(status IN ('PENDING','COMPLETED','FAILED','REFUNDED')), refunded_amount NUMBER(12,2) DEFAULT 0 NOT NULL CHECK(refunded_amount >= 0), created_at TIMESTAMP NOT NULL);
CREATE INDEX idx_memberships_validity ON MEMBERSHIPS(member_id,status,end_date);
CREATE INDEX idx_attendance_member_time ON ATTENDANCE(member_id,check_in_at);
CREATE INDEX idx_enrollment_class_status ON CLASS_ENROLLMENTS(class_id,status);
CREATE INDEX idx_payments_member_created ON PAYMENTS(member_id,created_at);
CREATE INDEX idx_classes_schedule ON GYM_CLASSES(scheduled_at,status);
